entries.commands:
# ===== 端口聚合（FortiOS）=====
config system interface
    edit "{{agg_name}}"
        set vdom "root"
        set type aggregate
        set member {{member_ports}}
        set lacp-mode {{lacp_mode}}
        set vlanforward enable
        set description "{{agg_desc}}"
    next
end
show system interface {{agg_name}}
diagnose netlink aggregate name {{agg_name}}

# ===== 静态路由（FortiOS）=====
config router static
    edit {{seq}}
        set dst {{dest_net}} {{dest_mask}}
        set gateway {{gateway}}
        set device "{{out_interface}}"
        set distance {{distance}}
        set comment "{{comment}}"
    next
    edit {{default_seq}}
        set dst 0.0.0.0 0.0.0.0
        set gateway {{gateway}}
        set device "{{out_interface}}"
        set distance {{default_distance}}
    next
end
show router static
get router info routing-table all

# ===== 配置查看与本地备份（FortiOS）=====
show full-configuration
execute backup config flash {{backup_name}}
diagnose sys flash list
# 插了 U 盘时可以直接备份到 U 盘（现场最常用）
# execute backup config usb {{backup_name}}
# 恢复配置（会覆盖当前配置，务必确认）
# execute restore config flash {{backup_name}}
